def get_loan_district_region(loan_id):
    loan_info = loan[loan['loan_id'] == loan_id]
    if not loan_info.empty:
        account_id = loan_info['account_id'].values[0]
        district_info = account[account['account_id'] == account_id]
        if not district_info.empty:
            district_id = district_info['district_id'].values[0]
            district_row = district[district['district_id'] == district_id]
            if not district_row.empty:
                return (district_row['A2'].values[0], district_row['A3'].values[0])
    return None
```

