def count_male_clients_in_hl_praha_district(clients, district):
    hl_praha_mask = district['A1'] == 'Hl.m. Praha'
    male_clients_in_hl_praha = clients[(clients['gender'] == 'M') & (clients['district_id'].isin(hl_praha_mask[district['A1']].index))]
    return len(male_clients_in_hl_praha)
```

